CREATE PROCEDURE [dbo].sp_UpdateQteTotalEns (@SOU_ID VARCHAR(20), @ITEM_ID VARCHAR(20), @CALCTIMSTP VARCHAR(14), @UID VARCHAR(14), @QTE_TOTAL FLOAT)
AS BEGIN
   IF @CALCTIMSTP = @UID 
   BEGIN
     UPDATE SOUPRO
     SET   QTEENS   = QTEENS + @QTE_TOTAL
     WHERE   SOU_ID = @SOU_ID
     AND     PRO_ID = @ITEM_ID 
   END ELSE
   BEGIN
     UPDATE SOUPRO
     SET QTEENS     = @QTE_TOTAL,
         CALCTIMSTP = @UID
     WHERE   SOU_ID = @SOU_ID
     AND     PRO_ID = @ITEM_ID     
   END
END
GO
