CREATE PROCEDURE [dbo].sp_FAC_UpdateQteTotalLots (@SOU_ID VARCHAR(20), @ITEM_ID VARCHAR(20), @CALCTIMSTP VARCHAR(14), @UID VARCHAR(14), @QTE_TOTAL FLOAT)
AS BEGIN
