     SET   QTELOT   = QTELOT + @QTE_TOTAL
     WHERE   SOU_ID = @SOU_ID
     AND     PRO_ID = @ITEM_ID 
   END ELSE
   BEGIN
     UPDATE FACPRO
     SET QTELOT     = @QTE_TOTAL,
         CALCTIMSTP = @UID
     WHERE   SOU_ID = @SOU_ID
     AND     PRO_ID = @ITEM_ID     
   END
END
