CREATE PROCEDURE [dbo].[up_BDEE_MULTI_Update] (
  @UniqueId   bigint,
  @DistributorCode  varchar(3),
  @ORDRE varchar(6),
  @DistributorName  varchar(40)
) AS

IF @UniqueId IS NULL
BEGIN
  --Insert new data into table
    [DistributorCode],
    [ORDRE],
    [DistributorName],
    SysDate)
  VALUES (
    @DistributorCode,
    @ORDRE,
    @DistributorName,
    GETDATE())

  --Return new ID
  RETURN @@IDENTITY
END ELSE
BEGIN
  --Update data into table
  UPDATE
    BDEE_MULTI
  SET
    [DistributorCode] = @DistributorCode,
    [ORDRE]           = @ORDRE,
    [DistributorName] = @DistributorName,
    SysDate           = GETDATE()
  WHERE
    UniqueId = @UniqueId

  --Return updated ID
  RETURN @UniqueId
END
GO

