CREATE FUNCTION [dbo].[fn_MultBlock](@SOU_ID VARCHAR(20), @BLO_ID_REL INT)
RETURNS float
AS BEGIN
   DECLARE @RES  FLOAT

   SELECT @RES = B.MULT
   FROM SOUBLO B
   WHERE B.BLO_ID = @BLO_ID_REL
     AND B.SOU_ID = @SOU_ID
   
   if @RES is null set @RES = 1;
   
   RETURN @RES;

END
GO

