CREATE FUNCTION [dbo].fn_UM_GetUniteDeBase(@CodeEN VARCHAR(2))
RETURNS VARCHAR(2)
AS BEGIN
  DECLARE @R VARCHAR(2)

  SELECT @R = P.BaseUnitCodeEN
  FROM Sys_Units P 
  WHERE P.CodeEN = @CodeEN

  RETURN @R

END
