CREATE FUNCTION [dbo].EE_Calgary()
RETURNS BIT
AS BEGIN
   DECLARE @RES  BIT

IF NOT EXISTS (
  SELECT 
    TOP 1 *
  FROM 
    INFORMATION_SCHEMA.COLUMNS
  WHERE 
        [TABLE_NAME]  = 'PRODUITS'
    AND [COLUMN_NAME] = 'LC' )
BEGIN
  SET @RES = 0;
END ELSE
BEGIN
  SET @RES = 1;
END;

RETURN @RES;

END
GO

